      115,
    );
  });

  it('discounts 15 % on each contract after the first', () => {
    // 100 base + 10 first insurance - 15 follow-up + 5 fee
    expect(quotePremium([{ type: 'sword' }], newcomer, 1)).toBe(100);
  });
});

